#!/usr/bin/env bash
# PreToolUse hook for Bash: block recursive forced removal (rm -rf and its
# spellings). Exit 2 blocks the call; stderr is shown to Claude as the reason.
# Needs python3. If this script cannot run, hooks.json's onFailure "block"
# blocks the call too, so the gate fails closed.
input=$(cat)
exec python3 -I - "$input" <<'PY'
import json
import os
import shlex
import sys

def is_separator(tok):
    return bool(tok) and all(c in ";&|()<>" for c in tok)

def split_segments(text):
    # Newlines and backticks end a command too; shlex does not treat them as separators.
    text = text.replace("\n", " ; ").replace("`", " ; ")
    lex = shlex.shlex(text, posix=True, punctuation_chars=True)
    lex.whitespace_split = True
    segments, current = [], []
    for tok in lex:
        if is_separator(tok):
            if current:
                segments.append(current)
            current = []
        else:
            current.append(tok)
    if current:
        segments.append(current)
    return segments

def recursive_force(args):
    short, long_opts = set(), []
    for arg in args:
        if arg == "--":
            break
        if arg.startswith("--"):
            long_opts.append(arg[2:])
        elif arg.startswith("-") and arg != "-":
            short.update(arg[1:])
    recursive = bool(short & {"r", "R"}) or any(o and "recursive".startswith(o) for o in long_opts)
    force = "f" in short or any(o and "force".startswith(o) for o in long_opts)
    return recursive and force

def blocked(text, depth=0):
    # Words with spaces (sh -c "rm -rf x", eval, ssh host "...") are re-checked as commands.
    if depth > 3:
        return False
    for segment in split_segments(text):
        for i, tok in enumerate(segment):
            if os.path.basename(tok) == "rm" and recursive_force(segment[i + 1:]):
                return True
        for tok in segment:
            if any(c.isspace() for c in tok) and blocked(tok, depth + 1):
                return True
    return False

try:
    event = json.loads(sys.argv[1])
    command = event.get("tool_input", {}).get("command", "")
    hit = isinstance(command, str) and blocked(command)
except ValueError:
    print("block-rm: could not parse the Bash command, so it is blocked to be safe.", file=sys.stderr)
    sys.exit(2)

if hit:
    print("block-rm: rm -rf (recursive forced removal) is blocked in this project. "
          "Remove the specific files by name, or ask the user to run it themselves.", file=sys.stderr)
    sys.exit(2)
