#!/bin/sh
# Stop gate: block stopping while `npm test` fails.
# Exit 2 blocks the stop and feeds stderr back to Claude as the reason.

cd "${CLAUDE_PROJECT_DIR:-$PWD}" || {
  echo "stop-gate: cannot cd to project directory" >&2
  exit 2
}

output=$(npm test 2>&1)
status=$?

if [ "$status" -ne 0 ]; then
  {
    echo "npm test is failing (exit $status). Fix the failures before stopping."
    echo "$output" | tail -n 200
  } >&2
  exit 2
fi

exit 0
EOF
